CREATE TABLE "CommerceOrder" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"tenantId" TEXT,"candidateId" TEXT,"kind" TEXT NOT NULL,"target" TEXT NOT NULL DEFAULT '',"snapshot" JSONB NOT NULL,"subtotal" INTEGER NOT NULL,"discount" INTEGER NOT NULL DEFAULT 0,"amount" INTEGER NOT NULL,"payeeSnapshot" JSONB NOT NULL,"status" TEXT NOT NULL DEFAULT 'AWAITING_PAYMENT',"utr" TEXT,"receiptKey" TEXT UNIQUE,"reason" TEXT,"approvedAt" TIMESTAMP(3),"consumedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CONSTRAINT commerce_amounts CHECK ("subtotal">0 AND "discount">=0 AND "amount"="subtotal"-"discount" AND "amount">0),
 CONSTRAINT commerce_owner CHECK (("tenantId" IS NOT NULL AND "candidateId" IS NULL) OR ("candidateId" IS NOT NULL AND "tenantId" IS NULL)));
CREATE INDEX "CommerceOrder_tenantId_candidateId_idx" ON "CommerceOrder"("tenantId","candidateId");
ALTER TABLE "CommerceOrder" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "CommerceOrder" FORCE ROW LEVEL SECURITY;
CREATE POLICY commerce_scope ON "CommerceOrder" USING (current_setting('app.role',true) IN ('SUPER_ADMIN','SYSTEM') OR (current_setting('app.role',true) IN ('TENANT_ADMIN','RECRUITER') AND "tenantId"=current_setting('app.tenant',true)) OR (current_setting('app.role',true)='CANDIDATE' AND "candidateId"=current_setting('app.candidate',true))) WITH CHECK (current_setting('app.role',true) IN ('SUPER_ADMIN','SYSTEM') OR (current_setting('app.role',true) IN ('TENANT_ADMIN','RECRUITER') AND "tenantId"=current_setting('app.tenant',true)) OR (current_setting('app.role',true)='CANDIDATE' AND "candidateId"=current_setting('app.candidate',true)));
